const item = $input.first().json;
const body = item.body ?? item;

let payload = null;
if (body?.payload) payload = body.payload;
else if (body?.body?.payload) payload = body.body.payload;
else if (body?.from) payload = body;
else if (body?.body?.from) payload = body.body;

const event = body?.event ?? item.event ?? 'message';
const allowedEvents = ['message', 'message.any'];
if (!payload || !allowedEvents.includes(event)) {
  return [{ json: { _skip: true, reason: `Non-message event or missing payload: ${event}`, rawPayload: JSON.stringify(body) } }];
}

if (payload.fromMe) {
  return [{ json: { _skip: true, reason: 'Skipping bot/fromMe message to prevent reply loop', rawPayload: JSON.stringify(body) } }];
}

const incomingChatId = payload.chatId || payload.from || '';
if (String(incomingChatId).includes('@g.us')) {
  return [{ json: { _skip: true, reason: 'Ignoring group message in owner-only mode', chatId: incomingChatId, rawPayload: JSON.stringify(body) } }];
}

const rawTimestamp = Number(payload.timestamp ?? body?.timestamp ?? 0);
const eventMs = rawTimestamp > 1000000000000 ? rawTimestamp : rawTimestamp * 1000;
const ageMs = eventMs ? Date.now() - eventMs : 0;
const maxAgeMs = 10 * 60 * 1000;
if (ageMs > maxAgeMs) {
  return [{ json: { _skip: true, reason: 'Skipping stale/backlog message', ageMs, eventTimestamp: new Date(eventMs).toISOString(), chatId: incomingChatId, rawPayload: JSON.stringify(body) } }];
}

const cleanPhone = (value) => String(value ?? '')
  .replace('@c.us', '')
  .replace('@g.us', '')
  .replace('@lid', '')
  .replace('@s.whatsapp.net', '')
  .replace(/[^0-9+]/g, '');

const exactChatId = payload.chatId || payload.from;
const remoteJidAlt = payload._data?.key?.remoteJidAlt || null;
const contactJid = remoteJidAlt || payload.from || exactChatId;
const senderPhone = cleanPhone(contactJid);
const replyTo = exactChatId || contactJid;
const media = payload.media ?? null;
const mediaUrl = media?.url ?? payload.mediaUrl ?? media?.link ?? null;
const mediaMimeType = media?.mimetype ?? media?.mimeType ?? payload.mimetype ?? payload._data?.message?.imageMessage?.mimetype ?? payload._data?.message?.audioMessage?.mimetype ?? null;
const rawType = String(payload.type ?? media?.type ?? payload._data?.messageType ?? '').toLowerCase();
const hasMedia = Boolean(payload.hasMedia || mediaUrl || mediaMimeType || media);

let messageType = rawType === 'chat' || !rawType ? 'text' : rawType;
if (hasMedia && (mediaMimeType?.startsWith('image/') || rawType.includes('image') || payload._data?.message?.imageMessage)) messageType = 'image';
if (hasMedia && (mediaMimeType?.startsWith('audio/') || rawType.includes('audio') || rawType === 'ptt' || payload._data?.message?.audioMessage)) messageType = 'audio';

const senderName = payload._data?.pushName ?? payload._data?.notifyName ?? payload.pushName ?? senderPhone;
const mediaDebug = {
  hasMedia,
  media,
  mediaUrl,
  mediaMimeType,
  mediaError: media?.error ?? null,
  payloadKeys: Object.keys(payload),
  dataKeys: Object.keys(payload._data ?? {}),
  exactChatId,
  remoteJidAlt,
};

return [{
  json: {
    senderPhone,
    replyTo,
    chatId: exactChatId,
    contactJid,
    remoteJidAlt,
    messageId: payload.id,
    messageType,
    timestamp: new Date((payload.timestamp ?? Date.now() / 1000) * 1000).toISOString(),
    textContent: payload.body ?? payload.caption ?? '',
    mediaId: mediaUrl,
    mediaUrl,
    mediaMimeType,
    mediaError: media?.error ?? null,
    hasMedia,
    senderName,
    waPhoneId: null,
    rawPayload: JSON.stringify(body),
    mediaDebug,
    _skip: false,
  }
}];

const { senderPhone, senderName, _skip } = $input.first().json;

if (_skip) return [$input.first()];

const BASE = $env.SUPABASE_URL;
const KEY = $env.SUPABASE_SERVICE_KEY;

if (!BASE || !KEY) {
  throw new Error('Missing SUPABASE_URL or SUPABASE_SERVICE_KEY');
}

const headers = {
  apikey: KEY,
  Authorization: `Bearer ${KEY}`,
  'Content-Type': 'application/json',
};

const rawPhone = String(senderPhone ?? '').trim();
const digits = rawPhone.replace(/[^0-9]/g, '');
const phoneCandidates = [...new Set([
  rawPhone,
  digits,
  digits.startsWith('62') ? `+${digits}` : null,
  rawPhone.startsWith('+') ? rawPhone.slice(1) : null,
].filter(Boolean))];

const inList = phoneCandidates.map(phone => `"${phone.replace(/"/g, '\\"')}"`).join(',');

let existing = [];
if (phoneCandidates.length > 0) {
  existing = await this.helpers.httpRequest({
    method: 'GET',
    url: `${BASE}/rest/v1/users?whatsapp_phone=in.(${encodeURIComponent(inList)})&select=id,whatsapp_phone,display_name,sheet_id,sheet_url`,
    headers,
    json: true,
  });
}

let user = Array.isArray(existing) && existing.length > 0 ? existing[0] : null;
let isNew = false;
const canonicalPhone = digits.startsWith('62') ? `+${digits}` : (rawPhone || digits);
const now = new Date().toISOString();

if (user) {
  try {
    const updated = await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${BASE}/rest/v1/users?id=eq.${user.id}`,
      headers: { ...headers, Prefer: 'return=representation' },
      body: { last_active_at: now },
      json: true,
    });
    user = Array.isArray(updated) && updated.length > 0 ? { ...user, ...updated[0] } : user;
  } catch (err) {
    console.log(`[Get or Create User] last_active_at update skipped: ${err.message}`);
  }
} else {
  try {
    const created = await this.helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/rest/v1/users?on_conflict=whatsapp_phone`,
      headers: {
        ...headers,
        Prefer: 'resolution=merge-duplicates,return=representation',
      },
      body: {
        whatsapp_phone: canonicalPhone,
        display_name: senderName ?? canonicalPhone,
        last_active_at: now,
      },
      json: true,
    });

    user = Array.isArray(created) ? created[0] : created;
    isNew = true;
  } catch (err) {
    if (err.httpCode !== 409 && err.statusCode !== 409 && err.response?.statusCode !== 409) {
      throw err;
    }

    const retry = await this.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/rest/v1/users?whatsapp_phone=eq.${encodeURIComponent(canonicalPhone)}&select=id,whatsapp_phone,display_name,sheet_id,sheet_url`,
      headers,
      json: true,
    });
    user = Array.isArray(retry) && retry.length > 0 ? retry[0] : null;
  }
}

if (!user?.id) {
  throw new Error(`Could not find or create user for ${rawPhone}`);
}

return [{ json: { ...($input.first().json), senderPhone: canonicalPhone, user: { ...user, isNew } } }];

const SB_URL = $env.SUPABASE_URL ?? '';
const SB_KEY = $env.SUPABASE_SERVICE_KEY ?? '';
const item = $input.first().json;

if (SB_URL && SB_KEY && !item._skip) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${SB_URL}/rest/v1/incoming_messages`,
      headers: {
        apikey: SB_KEY,
        Authorization: `Bearer ${SB_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal',
      },
      body: {
        user_id: item.user?.id ?? null,
        whatsapp_message_id: item.messageId,
        phone_from: item.senderPhone ?? null,
        message_type: item.messageType,
        raw_text: (item.textContent ?? '').slice(0, 2000) || null,
        payload: item.rawPayload,
        status: 'received',
        processed: false,
      },
      json: true,
    });
  } catch (err) {
    console.log(`[Log Incoming] Failed: ${err.message}`);
  }
}

return $input.all();

const item = $input.first().json;
const text = String(item.textContent ?? '').trim();
const lower = text.toLowerCase();

if (item._skip || !text) {
  return [{ json: { ...item, _skipExtraction: true, promptInput: null } }];
}

function parseAmount(input) {
  const match = String(input).toLowerCase().match(/(\d+(?:[,.]\d+)?)\s*(rb|ribu|k|jt|juta)?/i);
  if (!match) return null;
  let value = Number(match[1].replace(',', '.')) || 0;
  const unit = match[2] || '';
  if (/jt|juta/i.test(unit)) value *= 1000000;
  else if (/rb|ribu|k/i.test(unit)) value *= 1000;
  else if (value > 0 && value < 1000) value *= 1000;
  return Math.round(value);
}

const categoryMap = [
  ['pemasukan', /\b(pemasukan|masuk|jual|jualan)\b/],
  ['pengeluaran', /\b(pengeluaran|keluar|beli|belanja|bayar)\b/],
  ['hutang', /\b(hutang|utang)\b/],
  ['piutang', /\b(piutang)\b/],
  ['bayar_hutang', /\b(bayar_hutang|bayar hutang|bayar utang)\b/],
  ['terima_piutang', /\b(terima_piutang|terima piutang)\b/],
];

let commandIntent = null;

if (/^(laporan|ringkasan|rekap|summary)\b/.test(lower) || /(hari ini|bulan ini).*(berapa|total|keluar|masuk|untung|rugi)/.test(lower) || /^(utang|hutang|piutang)\s*(siapa|apa|berapa|list|daftar)?/.test(lower)) {
  let period = lower.includes('bulan') ? 'month' : 'today';
  if (/^(utang|hutang|piutang)/.test(lower)) period = 'open_debts';
  commandIntent = { type: 'query', period, raw: text };
}

if (/^(hapus|batalkan|delete|batal)\b/.test(lower) && /(terakhir|transaksi)/.test(lower)) {
  commandIntent = { type: 'delete_last', raw: text };
}

if (/^(koreksi|ubah|ganti|edit)\b/.test(lower)) {
  const updates = {};
  const amount = parseAmount(text);
  if (/nominal|harga|jumlah|jadi|ke/.test(lower) && amount) updates.nominal = amount;

  for (const [category, pattern] of categoryMap) {
    if (pattern.test(lower)) {
      updates.category = category;
      break;
    }
  }

  const itemMatch = text.match(/(?:item|barang|keterangan)\s+(.+)$/i);
  if (itemMatch) updates.item = itemMatch[1].trim();

  const pihakMatch = text.match(/(?:pihak|toko|orang|ke|dari)\s+([A-Za-z0-9 .'-]+)$/i);
  if (pihakMatch && !/nominal|kategori|item|barang/i.test(pihakMatch[1])) updates.pihak = pihakMatch[1].trim();

  commandIntent = { type: 'update_last', updates, raw: text };
}

if (commandIntent) {
  return [{
    json: {
      ...item,
      commandIntent,
      promptInput: text,
      processingMode: 'command',
      _skipExtraction: true,
    }
  }];
}

return [{
  json: {
    ...item,
    promptInput: text,
    processingMode: 'text',
    _skipExtraction: false,
  }
}];

const item = $input.first().json;

function normalizeWahaUrl(url) {
  if (!url) return null;
  const value = String(url);
  if (value.startsWith('/api/')) return `http://localhost:3000${value}`;
  if (value.startsWith('http://host.docker.internal:3000/')) return value.replace('http://host.docker.internal:3000/', 'http://localhost:3000/');
  return value;
}

function audioExtension(mime) {
  const clean = String(mime || '').split(';')[0].trim().toLowerCase();
  if (clean.includes('mpeg') || clean.includes('mp3')) return 'mp3';
  if (clean.includes('mp4')) return 'mp4';
  if (clean.includes('m4a')) return 'm4a';
  if (clean.includes('wav')) return 'wav';
  if (clean.includes('webm')) return 'webm';
  return 'ogg';
}

async function getLatestMediaUrl() {
  if (!item.chatId || !item.messageId) return null;

  const url = `http://localhost:3000/api/default/chats/${encodeURIComponent(item.chatId)}/messages/${encodeURIComponent(item.messageId)}?downloadMedia=true`;
  try {
    const msg = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: { 'X-Api-Key': 'wariskan123' },
      json: true,
      ignoreHttpStatusErrors: true,
    });

    const refreshed = Array.isArray(msg) ? msg[0] : msg;
    return refreshed?.media?.url || refreshed?.mediaUrl || null;
  } catch (err) {
    console.log(`[Download Audio Media] refresh failed: ${err.message}`);
    return null;
  }
}

let mediaUrl = normalizeWahaUrl(item.mediaUrl || item.mediaId || item.media?.url || item.media?.link);
if (!mediaUrl) mediaUrl = normalizeWahaUrl(await getLatestMediaUrl.call(this));

if (!mediaUrl) {
  return [{
    json: {
      ...item,
      audioDownloadFailed: true,
      audioDownloadReason: item.mediaError || 'WAHA received an audio message, but did not provide media.url yet.',
      processingMode: 'audio',
      transcript: '',
    }
  }];
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: mediaUrl,
    headers: { 'X-Api-Key': 'wariskan123' },
    encoding: 'arraybuffer',
    json: false,
  });

  const buffer = Buffer.isBuffer(response) ? response : Buffer.from(response);
  const rawMime = item.mediaMimeType || 'audio/ogg; codecs=opus';
  const mime = String(rawMime).split(';')[0].trim() || 'audio/ogg';
  const fileName = `wariskan-voice.${audioExtension(rawMime)}`;

  return [{
    json: {
      ...item,
      mediaUrl,
      mediaId: mediaUrl,
      audioBase64: buffer.toString('base64'),
      audioMimeType: rawMime,
      processingMode: 'audio',
    },
    binary: {
      audio: {
        data: buffer.toString('base64'),
        mimeType: mime,
        fileName,
      }
    }
  }];
} catch (err) {
  return [{
    json: {
      ...item,
      mediaUrl,
      mediaId: mediaUrl,
      audioDownloadFailed: true,
      audioDownloadReason: err.message,
      processingMode: 'audio',
      transcript: '',
    }
  }];
}

const item = $input.first().json;

function normalizeWahaUrl(url) {
  if (!url) return null;
  const value = String(url);
  if (value.startsWith('/api/')) return `http://localhost:3000${value}`;
  if (value.startsWith('http://host.docker.internal:3000/')) return value.replace('http://host.docker.internal:3000/', 'http://localhost:3000/');
  return value;
}

async function getLatestMediaUrl() {
  if (!item.chatId || !item.messageId) return null;

  const url = `http://localhost:3000/api/default/chats/${encodeURIComponent(item.chatId)}/messages/${encodeURIComponent(item.messageId)}?downloadMedia=true`;
  try {
    const msg = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: { 'X-Api-Key': 'wariskan123' },
      json: true,
      ignoreHttpStatusErrors: true,
    });

    const refreshed = Array.isArray(msg) ? msg[0] : msg;
    return refreshed?.media?.url || refreshed?.mediaUrl || null;
  } catch (err) {
    console.log(`[Download Image Media] refresh failed: ${err.message}`);
    return null;
  }
}

let mediaUrl = normalizeWahaUrl(item.mediaUrl || item.mediaId || item.media?.url || item.media?.link);
if (!mediaUrl) {
  mediaUrl = normalizeWahaUrl(await getLatestMediaUrl.call(this));
}

if (!mediaUrl) {
  return [{
    json: {
      ...item,
      imageDownloadFailed: true,
      imageDownloadReason: item.mediaError || 'WAHA received an image message, but did not provide media.url yet.',
      processingMode: 'image',
      textContent: item.textContent || 'Foto tidak bisa diunduh dari WAHA. Minta user kirim ulang foto yang sama.',
    }
  }];
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: mediaUrl,
    headers: { 'X-Api-Key': 'wariskan123' },
    encoding: 'arraybuffer',
    json: false,
  });

  const imageBase64 = Buffer.isBuffer(response)
    ? response.toString('base64')
    : Buffer.from(response).toString('base64');

  return [{
    json: {
      ...item,
      mediaUrl,
      mediaId: mediaUrl,
      imageBase64,
      mediaMimeType: item.mediaMimeType || 'image/jpeg',
      processingMode: 'image',
    }
  }];
} catch (err) {
  return [{
    json: {
      ...item,
      mediaUrl,
      mediaId: mediaUrl,
      imageDownloadFailed: true,
      imageDownloadReason: err.message,
      processingMode: 'image',
      textContent: item.textContent || 'Foto tidak bisa diunduh dari WAHA. Minta user kirim ulang foto yang sama.',
    }
  }];
}

const { messageType } = $input.first().json;

return [{
  json: {
    ...($input.first().json),
    to: $input.first().json.chatId || $input.first().json.replyTo || $input.first().json.senderPhone,
    replyText: `Maaf kak, saya belum bisa baca pesan ${messageType ?? 'jenis ini'}.\n\nSilakan kirim:\n- Pesan teks, contoh: "jual 350rb"\n- Pesan suara\n- Foto struk/nota`,
  }
}];

const item = $input.first().json;

if (item._skipExtraction || item.audioTranscriptionFailed) {
  return [{
    json: {
      ...item,
      content: [{ text: JSON.stringify({ category: 'unclear', nominal: 0, item: null, pihak: null, tanggal: null, jatuh_tempo: null, confidence: 'low' }) }],
      _usedFallbackExtraction: true,
    }
  }];
}

const inputText = item.promptInput || item.transcript || item.textContent || '';
if (!inputText.trim()) {
  return [{
    json: {
      ...item,
      content: [{ text: JSON.stringify({ category: 'unclear', nominal: 0, item: null, pihak: null, tanggal: null, jatuh_tempo: null, confidence: 'low' }) }],
      _usedFallbackExtraction: true,
    }
  }];
}

const system = [
  'Kamu adalah AI pencatat keuangan warung/toko kecil Indonesia.',
  'Ekstrak SATU transaksi utama dari pesan user.',
  'Kembalikan HANYA JSON valid tanpa markdown dan tanpa teks tambahan.',
  'Format: {"category":"pengeluaran","nominal":0,"item":null,"pihak":null,"tanggal":null,"jatuh_tempo":null,"confidence":"high"}',
  'Kategori valid: pemasukan, pengeluaran, hutang, piutang, bayar_hutang, terima_piutang, unclear.',
  'Aturan umum: jual/terima/dapat/setoran/omset = pemasukan. beli/bayar/belanja/modal/ongkos/sewa = pengeluaran.',
  'Kalimat orang lain berutang ke user = piutang. User berutang ke orang lain = hutang.',
  'Nominal harus angka rupiah penuh TANPA titik/koma pemisah ribuan. 51 ribu = 51000, 350rb = 350000, 50.000 = 50000, 1,5jt = 1500000, 1.2 juta = 1200000, 2 juta = 2000000.',
  'item ringkas dan natural. pihak isi nama orang/toko jika disebut.',
  'Jika tidak yakin, category unclear, nominal 0, confidence low.'
].join('\n');

const models = [
  $env.ANTHROPIC_EXTRACT_MODEL,
  $env.ANTHROPIC_MODEL,
  'claude-3-5-haiku-20241022',
  'claude-sonnet-4-20250514',
].filter(Boolean);

let lastResponse = null;
let usedModel = null;
for (const model of [...new Set(models)]) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: {
      model,
      max_tokens: 500,
      system,
      messages: [{ role: 'user', content: inputText }],
    },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  lastResponse = response;
  if (!response?.error) {
    usedModel = model;
    break;
  }

  const errorType = response.error?.type ?? response.type;
  if (errorType !== 'not_found_error') break;
}

if (lastResponse?.error) {
  return [{
    json: {
      ...item,
      ...lastResponse,
      message: lastResponse,
      aiExtractFailed: true,
      aiExtractError: lastResponse.error?.message || 'Anthropic extraction failed',
      ai_model_version: usedModel || 'anthropic-extract-unavailable',
      _usedFallbackExtraction: true,
    }
  }];
}

return [{
  json: {
    ...item,
    ...lastResponse,
    message: lastResponse,
    ai_model_version: usedModel,
  }
}];

const item = $input.first().json;

if (item.imageDownloadFailed || !item.imageBase64) {
  return [{
    json: {
      ...item,
      content: [{ text: JSON.stringify({ category: 'unclear', nominal: 0, item: null, pihak: null, tanggal: null, jatuh_tempo: null, confidence: 'low' }) }],
      ai_model_version: 'media-download-fallback',
      _usedFallbackExtraction: true,
    }
  }];
}

const system = [
  'Kamu adalah AI pencatat keuangan warung/toko kecil Indonesia.',
  'Tugasmu membaca foto struk, nota, bukti transfer, atau catatan belanja dari WhatsApp.',
  'Ekstrak SATU transaksi utama yang paling jelas dari gambar.',
  'Kembalikan HANYA JSON valid tanpa markdown dan tanpa teks tambahan.',
  'Format: {"category":"pengeluaran","nominal":0,"item":null,"pihak":null,"tanggal":null,"jatuh_tempo":null,"confidence":"high"}',
  'Kategori valid: pemasukan, pengeluaran, hutang, piutang, bayar_hutang, terima_piutang, unclear.',
  'Untuk struk belanja, default category adalah pengeluaran.',
  'nominal harus angka rupiah penuh TANPA titik/koma pemisah ribuan. Baca 51.000 sebagai 51000, 1.250.000 sebagai 1250000, 1,5jt sebagai 1500000. Gunakan total akhir kalau terlihat, bukan subtotal per item.',
  'item berisi ringkasan belanja, misalnya "Belanja sembako" atau nama merchant/item utama.',
  'pihak berisi merchant/toko/pengirim jika terlihat.',
  'Jika gambar tidak terbaca, category unclear, nominal 0, confidence low.'
].join('\n');

const models = [
  $env.ANTHROPIC_VISION_MODEL,
  $env.ANTHROPIC_MODEL,
  'claude-sonnet-4-20250514',
  'claude-3-7-sonnet-20250219',
  'claude-3-5-haiku-20241022',
].filter(Boolean);

let lastResponse = null;
let usedModel = null;

for (const model of [...new Set(models)]) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: {
      model,
      max_tokens: 700,
      system,
      messages: [
        {
          role: 'user',
          content: [
            {
              type: 'image',
              source: {
                type: 'base64',
                media_type: item.mediaMimeType || 'image/jpeg',
                data: item.imageBase64,
              },
            },
            {
              type: 'text',
              text: item.textContent
                ? `Caption user: ${item.textContent}\n\nEkstrak transaksi dari gambar ini.`
                : 'Ekstrak transaksi dari gambar ini.',
            },
          ],
        },
      ],
    },
    json: true,
    ignoreHttpStatusErrors: true,
  });

  lastResponse = response;
  if (!response?.error) {
    usedModel = model;
    break;
  }

  const errorType = response.error?.type ?? response.type;
  if (errorType !== 'not_found_error') {
    break;
  }
}

if (lastResponse?.error) {
  return [{
    json: {
      ...item,
      ...lastResponse,
      message: lastResponse,
      aiVisionFailed: true,
      aiVisionError: lastResponse.error?.message ?? 'Anthropic Vision request failed',
      ai_model_version: usedModel ?? 'anthropic-vision-unavailable',
      _usedFallbackExtraction: true,
    }
  }];
}

