function parseMoneyCandidate(raw, unit = '') {
  if (raw == null || raw === '') return 0;
  let s = String(raw).trim().toLowerCase();
  unit = String(unit || '').toLowerCase();

  s = s.replace(/^rp\s*/i, '').replace(/\s+/g, '');
  s = s.replace(/[^0-9.,]/g, '');
  if (!s) return 0;

  const hasUnit = /(rb|ribu|k|jt|juta|mio|milyar|miliar|m)/i.test(unit);
  let value = 0;

  if (hasUnit) {
    // With explicit units, one separator is decimal: 1,5jt / 1.5 juta.
    const normalized = s.replace(',', '.');
    value = Number(normalized.replace(/\.(?=.*\.)/g, '')) || 0;
  } else if (/^\d{1,3}([.,]\d{3})+$/.test(s)) {
    // 50.000 / 1.250.000 / 50,000 are thousands separators.
    value = Number(s.replace(/[.,]/g, '')) || 0;
  } else if (/^\d+[.,]\d{1,2}$/.test(s)) {
    // Ambiguous decimal without unit, keep numeric value first.
    value = Number(s.replace(',', '.')) || 0;
  } else {
    value = Number(s.replace(/[.,]/g, '')) || 0;
  }

  if (/^(jt|juta|mio)$/i.test(unit)) value *= 1000000;
  else if (/^(milyar|miliar|m)$/i.test(unit)) value *= 1000000000;
  else if (/^(rb|ribu|k)$/i.test(unit)) value *= 1000;
  else if (value > 0 && value < 1000) value *= 1000;

  return Math.round(value);
}

function parseMoneyFromText(text) {
  const source = String(text || '').toLowerCase();
  if (!source.trim()) return 0;

  const candidates = [];
  const pattern = /(?:rp\s*)?(\d+(?:[.,]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?)(?:\s*)(rb|ribu|k|jt|juta|mio|milyar|miliar|m)?\b/gi;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    const before = source.slice(Math.max(0, match.index - 12), match.index);
    const after = source.slice(pattern.lastIndex, pattern.lastIndex + 14);

    // Avoid common non-money contexts if there is no explicit unit/currency.
    const hasMoneyHint = Boolean(match[2]) || /rp\s*$/i.test(before) || /harga|total|nominal|bayar|jual|jualan|beli|belanja|utang|hutang|piutang|masuk|keluar|omset|setoran/i.test(source);
    if (!hasMoneyHint) continue;
    if (!match[2] && /\b(kg|gram|gr|pcs|buah|liter|ltr|l|botol|bungkus|pack|dus|tanggal|tgl|jam)\b/i.test(after)) continue;

    const amount = parseMoneyCandidate(match[1], match[2]);
    if (amount > 0) candidates.push(amount);
  }

  if (!candidates.length) return 0;
  return Math.max(...candidates);
}

function normalizeNominal(value, sourceText) {
  const fromValue = typeof value === 'string'
    ? parseMoneyCandidate(value, '')
    : Math.round(Number(value || 0));
  const fromText = parseMoneyFromText(sourceText);

  // Prefer source text when it clearly finds a larger rupiah value. This fixes JSON number 50.000 parsed as 50.
  if (fromText > fromValue) return fromText;
  if (fromValue > 0 && fromValue < 1000 && fromText === 0) return fromValue * 1000;
  return fromValue || fromText || 0;
}

function buildFallback(text) {
  const lower = String(text).toLowerCase();
  const nominal = parseMoneyFromText(lower);

  let category = 'unclear';
  if (/\b(jual|jualan|terima|dapat|dapet|masuk|pemasukan|setoran|omset|pendapatan)\b/i.test(lower)) category = 'pemasukan';
  else if (/(udah|sudah|telah).*(bayar|balik|lunasin).*(utang|hutang)|dibayar.*(utang|hutang)/i.test(lower)) category = 'terima_piutang';
  else if (/(si|pak|bu|mbak|mas)\s+\w+.*(minjam|minjem|ngutang|utang|hutang)|dipinjam|ngasih.*pinjam|pinjamin/i.test(lower)) category = 'piutang';
  else if (/(bayar|nyicil|lunas).*(hutang|utang)/i.test(lower)) category = 'bayar_hutang';
  else if (/\b(hutang|utang|ngutang|pinjam.*dari|minjam.*dari|minjem.*dari)\b/i.test(lower)) category = 'hutang';
  else if (/\b(beli|bayar|keluar|pengeluaran|belanja|modal|kasbon|ongkos|sewa)\b/i.test(lower)) category = 'pengeluaran';

  let item = null;
  const itemMatch = lower.match(/(?:beli|jual|jualan|bayar)\s+([^0-9]+)/i);
  if (itemMatch) item = itemMatch[1].replace(/\b(rb|ribu|k|jt|juta|mio|milyar|miliar|rp)\b/gi, '').trim() || null;

  return { category, nominal, item, pihak: null, tanggal: null, jatuh_tempo: null, confidence: 'low' };
}

