function buildSummary(rows, today) {
  const summary = rows.reduce((acc, row) => {
    const amount = Number(row.nominal || 0);
    const isToday = row.tanggal === today;
    if (row.category === 'pemasukan' || row.category === 'terima_piutang') {
      acc.monthIn += amount;
      if (isToday) acc.todayIn += amount;
    }
    if (row.category === 'pengeluaran' || row.category === 'bayar_hutang') {
      acc.monthOut += amount;
      if (isToday) acc.todayOut += amount;
    }
    if (row.category === 'hutang' && row.status === 'aktif') acc.hutang += amount;
    if (row.category === 'piutang' && row.status === 'aktif') acc.piutang += amount;
    return acc;
  }, { monthIn: 0, monthOut: 0, todayIn: 0, todayOut: 0, hutang: 0, piutang: 0 });
  summary.monthNet = summary.monthIn - summary.monthOut;
  summary.todayNet = summary.todayIn - summary.todayOut;
