    health,
  ].join('\n');

  const debts = data.commandResult.debtRows || [];
  if (debts.length) {
    replyText += '\n\nHutang/piutang terbaru:';
    for (const row of debts.slice(0, 5)) {
      replyText += `\n- ${row.category}: ${money(row.nominal)}${row.pihak ? ` (${row.pihak})` : ''}${row.item ? ` - ${row.item}` : ''}${row.jatuh_tempo ? ` | tempo ${row.jatuh_tempo}` : ''}`;
    }
  } else {
    replyText += '\n\nBelum ada hutang/piutang aktif yang tercatat.';
  }

  replyText += '\n\nKetik: hutang / piutang / hapus terakhir / koreksi nominal 52000';
  return [{ json: { ...data, replyText, to: OWNER_JID } }];
}

if (data.commandResult?.type === 'delete_last') {
  const tx = data.commandResult.transaction;
  let replyText = data.commandResult.notFound
    ? 'Belum ada transaksi aktif yang bisa aku hapus.'
    : `Oke, transaksi terakhir aku batalkan.\n${tx.category}: ${money(tx.nominal)}${tx.item ? ` - ${tx.item}` : ''}`;
  if (!data.commandResult.notFound) {
    if (data.sheetSynced) replyText += '\nGoogle Sheet juga sudah aku coret.';
    else if (data.sheetSyncError) replyText += `\nCatatan: database sudah berubah, tapi Sheet belum tersinkron (${String(data.sheetSyncError).slice(0, 90)}).`;
  }
  return [{ json: { ...data, replyText, to: OWNER_JID } }];
}

if (data.commandResult?.type === 'update_last') {
  const tx = data.commandResult.transaction;
  let replyText = 'Aku belum menangkap koreksinya. Contoh: koreksi nominal 52000';
  if (data.commandResult.notFound) replyText = 'Belum ada transaksi aktif yang bisa aku koreksi.';
  else if (tx) {
    replyText = `Siap, transaksi terakhir sudah aku koreksi.\n${tx.category}: ${money(tx.nominal)}${tx.item ? ` - ${tx.item}` : ''}${tx.pihak ? `\nPihak: ${tx.pihak}` : ''}`;
    if (data.sheetSynced) replyText += '\nGoogle Sheet juga sudah ikut update.';
    else if (data.sheetSyncError) replyText += `\nCatatan: database sudah berubah, tapi Sheet belum tersinkron (${String(data.sheetSyncError).slice(0, 90)}).`;
  }
  return [{ json: { ...data, replyText, to: OWNER_JID } }];
}

if (data.saveFailed) {
  const ext = data.extractedData ?? {};
  const detail = data.saveError ? `\nDetail teknis: ${String(data.saveError).slice(0, 220)}` : '';
  return [{ json: { ...data, replyText: `Belum bisa aku simpan ke database.\nYang terbaca: ${ext.category || 'unclear'} - ${money(ext.nominal || 0)}${detail}\n\nTolong cek Supabase/env sebelum demo.`, to: OWNER_JID } }];
}

if (data.duplicateTransaction) {
  const tx = data.savedTransaction || {};
  return [{ json: { ...data, replyText: `Pesan ini sudah pernah aku catat, jadi tidak aku duplikat.\n${tx.category || 'Transaksi'}: ${money(tx.nominal)}`, to: OWNER_JID } }];
}

const tx = data.savedTransaction || data.saveResult || {};
const ext = data.extractedData ?? {};
const category = tx.category || ext.category || 'unclear';
const nominal = Number(tx.nominal ?? ext.nominal ?? 0) || 0;
const labels = {
  pemasukan: 'Pemasukan',
  pengeluaran: 'Pengeluaran',
  hutang: 'Hutang',
  piutang: 'Piutang',
  bayar_hutang: 'Bayar hutang',
  terima_piutang: 'Terima piutang',
  unclear: 'Tidak jelas',
};
const signs = {
  pemasukan: '+',
  terima_piutang: '+',
  pengeluaran: '-',
  bayar_hutang: '-',
  hutang: '!',
  piutang: '!',
  unclear: '?',
};

let summary = null;
try {
  const BASE = $env.SUPABASE_URL;
  const KEY = $env.SUPABASE_SERVICE_KEY;
  if (BASE && KEY && data.user?.id) {
    const headers = { apikey: KEY, Authorization: `Bearer ${KEY}` };
    const startMonth = new Date();
    startMonth.setDate(1);
    const monthDate = startMonth.toISOString().slice(0, 10);
    const today = new Date().toISOString().slice(0, 10);
    const rows = await this.helpers.httpRequest({
      method: 'GET',
      url: `${BASE}/rest/v1/transactions?user_id=eq.${data.user.id}&tanggal=gte.${monthDate}&status=eq.aktif&select=id,category,nominal,tanggal,status`,
      headers,
      json: true,
      ignoreHttpStatusErrors: true,
    });
    if (Array.isArray(rows)) {
      const summaryRows = [...rows];
      if (tx?.id && tx.status !== 'dibatalkan' && !summaryRows.some((row) => row.id === tx.id)) {
        summaryRows.push({ id: tx.id, category, nominal, tanggal: tx.tanggal || today, status: tx.status || 'aktif' });
      }
      summary = summaryRows.reduce((acc, row) => {
        const amount = Number(row.nominal || 0);
        const isToday = row.tanggal === today;
        if (row.category === 'pemasukan' || row.category === 'terima_piutang') { acc.monthIn += amount; if (isToday) acc.todayIn += amount; }
        if (row.category === 'pengeluaran' || row.category === 'bayar_hutang') { acc.monthOut += amount; if (isToday) acc.todayOut += amount; }
        if (row.category === 'hutang') acc.hutang += amount;
        if (row.category === 'piutang') acc.piutang += amount;
        return acc;
      }, { monthIn: 0, monthOut: 0, todayIn: 0, todayOut: 0, hutang: 0, piutang: 0 });
      summary.monthNet = summary.monthIn - summary.monthOut;
      summary.todayNet = summary.todayIn - summary.todayOut;
    }
  }
} catch (err) {
  console.log(`[Build Reply Message] summary skipped: ${err.message}`);
}

const isWeak = category === 'unclear' || nominal <= 0 || data._usedFallbackExtraction || ext.confidence === 'low';
if (isWeak) {
  let replyText = `Aku belum yakin ini transaksi yang benar.\nNominal terbaca: ${money(nominal)}\n`;
  if (tx.item || ext.item) replyText += `Item: ${tx.item || ext.item}\n`;
  replyText += `\nTolong koreksi atau kirim ulang ya.\n\n${examples()}`;
  return [{ json: { ...data, replyText, to: OWNER_JID, summary } }];
}

const itemLine = tx.item || ext.item || labels[category] || 'Transaksi';
let replyText = `Siap, aku catat.\n\n${signs[category] || ''} ${money(nominal)}\n${itemLine}`;
if (tx.pihak || ext.pihak) replyText += `\nPihak: ${tx.pihak || ext.pihak}`;
if (data.transcript) replyText += `\n\nAku dengar: "${String(data.transcript).slice(0, 160)}"`;

if (data.sheetSaved) {
  replyText += data.sheetCreated ? `\n\nGoogle Sheet baru sudah dibuat dan transaksi tersimpan.` : `\n\nTersimpan di Google Sheet.`;
} else if (data.sheetSkipped) {
  replyText += data.sheetCreateError
    ? `\n\nGoogle Sheet belum dibuat (${String(data.sheetCreateError).slice(0, 90)}).`
    : `\n\nGoogle Sheet belum aktif untuk user ini.`;
} else if (data.sheetError) {
  replyText += `\n\nGoogle Sheet belum tersimpan (${String(data.sheetError).slice(0, 90)}).`;
}

if (summary) {
  replyText += `\n\nHari ini: ${signedMoney(summary.todayNet)}\nBulan ini: ${signedMoney(summary.monthNet)}`;
  if (summary.hutang || summary.piutang) replyText += `\nHutang ${money(summary.hutang)} - Piutang ${money(summary.piutang)}`;
}

replyText += `\n\nKalau salah, balas: koreksi nominal 52000 / hapus terakhir / ringkasan`;

return [{ json: { ...data, replyText, to: OWNER_JID, summary } }];

