let original = {};
try {
  original = $('Download Audio Media').first().json || {};
} catch (err) {
  original = {};
}

const response = $input.first().json || {};
const transcript = response.text || response.transcript || response.data?.text || '';
const errorMessage = response.error?.message || response.message || response.error || '';

if (original.audioDownloadFailed) {
  return [{
    json: {
      ...original,
      audioTranscriptionFailed: true,
      audioTranscriptionError: original.audioDownloadReason || 'Audio download failed',
      transcript: '',
      textContent: '',
      ai_model_version: 'openai-transcription-unavailable',
    }
  }];
}

if (!transcript.trim()) {
  return [{
    json: {
      ...original,
      openaiTranscription: response,
      audioTranscriptionFailed: true,
      audioTranscriptionError: errorMessage || 'OpenAI returned an empty transcript',
      transcript: '',
      textContent: '',
      ai_model_version: 'openai-transcription-unavailable',
    }
  }];
}

return [{
  json: {
    ...original,
    transcript,
    textContent: transcript,
    openaiTranscription: response,
    ai_model_version: $env.OPENAI_TRANSCRIBE_MODEL || 'gpt-4o-mini-transcribe',
  }
}];
